def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_last = history[n - 1][1]
    my_last = history[n - 1][0]

    # Opponent move counts
    total_opp_c = 0
    total_opp_d = 0
    total_my_d = 0
    for a, b in history:
        if b == 'C':
            total_opp_c += 1
        else:
            total_opp_d += 1
        if a == 'D':
            total_my_d += 1

    # Instant punitive response to defection, with strict forgiveness.
    if opp_last == 'D':
        if my_last == 'D':
            return 'D'
        return 'D'

    # Opponent cooperated on last move.
    # Detect pure always-cooperator / very cooperative.
    if total_opp_d == 0:
        # Exploit endgame, but only very late.
        if n >= 95:
            return 'D'
        return 'C'

    opp_c = total_opp_c
    opp_d = total_opp_d
    coop_rate = opp_c / n

    # If opponent is highly cooperative, mostly cooperate with sparse probes.
    if coop_rate >= 0.8:
        if n >= 90:
            return 'D'
        # Sparse probing to detect exploitable opponents.
        if n > 25 and n % 19 == 0:
            return 'D'
        return 'C'

    # If opponent is mostly defecting, defect defensively.
    if coop_rate < 0.35:
        return 'D'

    # Recover from our own defection.
    if my_last == 'D':
        # Return to cooperation unless opponent is dangerous.
        if coop_rate >= 0.5:
            return 'C'
        return 'D'

    # Moderate opponent: retaliate that just occurred has been handled.
    # Use recent window to detect current mood.
    start = n - 10 if n > 10 else 0
    recent_c = 0
    recent_total = n - start
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_c += 1
    if recent_total > 0:
        recent_rate = recent_c / recent_total
    else:
        recent_rate = coop_rate

    # Opponent just cooperated and recent mood is cooperative: cooperate.
    if recent_rate >= 0.6:
        # Endgame exploitation against cooperative opponents.
        if n >= 95:
            return 'D'
        return 'C'

    # Recent mood mixed/defective but last was C: cautious cooperate to probe.
    if recent_rate >= 0.3:
        if rng.random() < 0.6:
            return 'C'
        return 'D'

    return 'D'
